"""Purpose: apply the reviewed compact v6 UI patch, saved before workflow execution.
Setup: decoded source targets the inspected v0.5.0 files with exact-anchor checks.
Writes: picker HTML/JS/CSS, matching option, default image size and version metadata.
Constraints: no catalog/photo changes, no shopping requests or changes to cart validation.
The compressed payload is the complete UTF-8 Python patch, not a downloaded program.
"""
import base64, hashlib, subprocess, zlib
payload = ''''''
source = zlib.decompress(base64.b64decode(payload))
assert hashlib.sha256(source).hexdigest() == 'f22b0d255f27eac426dce916923084306a07ae91d20c2b855b2bde74087ebee3'
subprocess.run(['python', '-c', source.decode('utf-8')], check=True)
